"</style></head>\n"
"<body><main><header><span class=\"brand\">♫ LYRICFLASH</span><nav aria-label=\"Main navigation\"><a href=\"/\" class=\"active\">Settings</a><a href=\"/firmware\">Firmware</a></nav></header>\n"
"<h1>Device Settings</h1><p>Wi-Fi, clock faces, weather and device preferences. Firmware installation has its own maintenance page.</p>\n"
"<section><h2>Wi-Fi</h2><p id=\"wifi-state\">Checking Wi-Fi…</p><button id=\"scan\" type=\"button\" class=\"outline\">Scan nearby 2.4 GHz networks</button>\n"
"<label>Nearby networks<select id=\"networks\"><option value=\"\">Choose a network</option></select></label>\n"
"<label>Home Wi-Fi name<input id=\"ssid\" placeholder=\"Network name\" maxlength=\"32\" autocomplete=\"off\"></label>\n"
"<label>Home Wi-Fi password<input id=\"pass\" type=\"password\" placeholder=\"Your home network password\" autocomplete=\"new-password\"></label>\n"
"<button id=\"wifi-save\" type=\"button\">Save Wi-Fi &amp; reconnect</button><div id=\"wifi-status\" class=\"status\" role=\"status\"></div>\n"
"<p class=\"muted\">No PIN or on-device authorization required. Saving new Wi-Fi may disconnect this browser.</p></section>\n"
"<section><h2>Clock &amp; Weather</h2><p>Choose your clock face, set its appearance and manage the weather location and refresh interval.</p>\n"
"<a class=\"action\" href=\"/settings\">Open Clock Studio</a></section>\n"
"<section><h2>Lyrics &amp; Display</h2><p>Lyric preview speed, brightness and other display controls are available on-device while browser controls are developed.</p></section>\n"
"<section><h2>Diagnostics</h2><button id=\"diagnostics-btn\" class=\"outline\" type=\"button\">Refresh status</button>\n"
"<pre id=\"diagnostics\">Not yet loaded.</pre></section>\n"
"<section><h2>Maintenance</h2><p class=\"muted\">Updating or restoring firmware is a separate task.</p><a href=\"/firmware\">Open Firmware page</a></section>\n"
"</main><script>\n"
"const el=id=>document.getElementById(id), message=v=>el('wifi-status').textContent=v;\n"
"async function get(url){let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);return r.json()}\n"
"async function load(){try{let d=await get('/api/info');el('wifi-state').textContent=d.connected_ssid?'Connected: '+d.connected_ssid:d.saved_ssid?'Saved: '+d.saved_ssid+' (disconnected)':'No home Wi-Fi saved';if(d.saved_ssid)el('ssid').value=d.saved_ssid}catch(e){el('wifi-state').textContent='Wi-Fi status unavailable: '+e.message}}\n"
"async function poll(n){try{let data=await get('/api/wifi-scan');if(data.state==='scanning'&&n<18){setTimeout(()=>poll(n+1),700);return}\n"
"let sel=el('networks');sel.replaceChildren(new Option('Choose a network',''));\n"
"for(let x of data.networks||[])sel.add(new Option(x.ssid+(x.secured?' • secured':''),x.ssid));\n"
"message(data.state==='ready'?'Networks found: '+(data.networks||[]).length:'No networks found. Try scanning again.')}catch(e){message('Wi-Fi scan failed: '+e.message)}}\n"
"el('scan').onclick=async()=>{message('Scanning…');try{await get('/api/wifi-scan?refresh=1');poll(0)}catch(e){message('Scan unavailable: '+e.message)}};\n"
"el('networks').onchange=()=>{if(el('networks').value)el('ssid').value=el('networks').value};\n"
"el('wifi-save').onclick=async()=>{let ssid=el('ssid').value.trim(),password=el('pass').value;if(!ssid)return message('Choose a Wi-Fi network');\n"
"try{message('Saving…');let r=await fetch('/wifi',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ssid,password})});message(await r.text());if(r.ok)el('pass').value=''}catch(e){message('Failed to save: '+e.message)}};\n"
"el('diagnostics-btn').onclick=async()=>{try{el('diagnostics').textContent=JSON.stringify(await get('/api/diagnostics'),null,2)}catch(e){el('diagnostics').textContent='Unavailable: '+e.message}};\n"
"load();el('diagnostics-btn').click();\n"
"</script></body></html>\n"
;
static const char lf_device_firmware_html[] =
"<!doctype html>\n"
"<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>LyricFlash | Firmware</title><style>\n"
"*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0%,#132d51,#07111e 66%);color:#eaf5ff;font:15px system-ui,sans-serif}\n"
"main{max-width:760px;margin:auto;padding:25px 18px 65px}header{display:flex;justify-content:space-between;gap:15px;align-items:center;border-bottom:1px solid #38516b;padding:0 0 17px}\n"
".brand{font-weight:850;letter-spacing:.09em;color:#91e9d7}nav{display:flex;gap:12px}nav a{padding:9px 12px;border-radius:9px;color:#b7cee3;text-decoration:none}\n"
"nav a.active{background:#83cfff;color:#061423;font-weight:750}h1{margin:24px 0 6px;font-size:29px}h2{margin:0 0 8px;font-size:20px}\n"
"section{background:#131f30;border:1px solid #34536f;border-radius:18px;padding:20px;margin:19px 0}\n"
"p{color:#afc5d8;line-height:1.55}label{display:block;font-size:13px;margin:12px 0 6px;color:#cdddea}\n"
"select,input,button{font:inherit}input,select{width:100%;background:#071524;color:#fff;border:1px solid #56738b;border-radius:10px;padding:12px}\n"
"button,.action{display:inline-block;border:0;background:#8bd0ff;color:#061d33;padding:12px 16px;margin-top:12px;border-radius:10px;font-weight:760;cursor:pointer;text-decoration:none}\n"
"button:disabled{opacity:.45;cursor:wait}.outline{background:transparent;border:1px solid #779db7;color:#d8ecff}.muted{font-size:13px;color:#95b0c6}\n"
".notice{border-left:3px solid #83cfff;padding:10px 13px;background:#10243b;color:#c1d8ec;border-radius:8px}.status{white-space:pre-wrap;overflow-wrap:anywhere;color:#c1e8ff;margin-top:11px}\n"
"pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace,monospace;color:#b6cce0}\n"
"</style></head>\n"
"<body><main><header><span class=\"brand\">♫ LYRICFLASH</span><nav aria-label=\"Main navigation\"><a href=\"/\">Settings</a><a class=\"active\" href=\"/firmware\">Firmware</a></nav></header>\n"
"<h1>Firmware &amp; Recovery</h1><p>Maintenance tools are kept away from everyday configuration. No PIN or ARM step is required.</p>\n"
"<section><h2>Current firmware</h2><p id=\"installed\">Reading installed version…</p><p class=\"muted\" id=\"ota-status\"></p></section>\n"
"<section><h2>Install directly from GitHub</h2><p>Select a published LyricFlash version. The device downloads and validates the OTA firmware over HTTPS—no file upload required.</p>\n"
"<label>Available builds<select id=\"builds\"><option value=\"\">Loading GitHub builds…</option></select></label>\n"
"<div id=\"build-info\" class=\"muted\">Only published, downloadable builds are offered. Successful Actions runs alone are not releases.</div>\n"
"<button type=\"button\" id=\"install\" disabled>Install selected OTA version</button>\n"
"<div class=\"status\" id=\"fwstatus\" role=\"status\" aria-live=\"polite\"></div>\n"
"<p class=\"muted\">Updates preserve saved Wi-Fi and settings. Your device must be connected to Wi-Fi with internet access to download from GitHub.</p></section>\n"
"<section><h2>Manual OTA fallback</h2><p>Use this only if GitHub is temporarily unavailable. Select an application-only LyricFlash OTA .bin file, not the full USB recovery image.</p>\n"
"<label>Application-only OTA file<input id=\"bin\" type=\"file\" accept=\".bin,application/octet-stream\"></label>\n"
"<button id=\"upload\" type=\"button\" class=\"outline\">Install local OTA file</button><div id=\"upload-status\" class=\"status\"></div></section>\n"
"<section><h2>Factory / USB recovery</h2><p>Full USB recovery is separate from OTA. It can erase all saved Wi-Fi and settings. Never install a merged full USB image through the OTA controls.</p>\n"
"<a href=\"https://skiiirt1983.github.io/LyricFlash/restore/\" target=\"_blank\" rel=\"noopener\">Factory restore instructions (USB only)</a></section>\n"
"</main><script>\n"
"const el=id=>document.getElementById(id), info=v=>el('fwstatus').textContent=v;\n"
"let installed='', entries=[];\n"
"async function get(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);return r.json();}\n"
"async function loadInstalled(){try{let d=await get('/api/info');installed=d.version||'';el('installed').textContent='Installed: '+installed;el('ota-status').textContent='OTA: '+(d.ota_result||'idle');}catch(e){el('installed').textContent='Could not read installed version';}}\n"
"async function loadBuilds(){\n"
" entries=[];const errors=[];\n"
" try{\n"
" const releases=await get('https://api.github.com/repos/skiiirt1983/LyricFlash/releases?per_page=30');\n"
" for(const r of releases){for(const a of r.assets||[]){\n"
" if(!/^(?:lyricflash[-_.].*[-_.])?ota(?:[-_.].*)?\\.bin$/i.test(a.name)&&!/^lyricflash-ota\\.bin$/i.test(a.name))continue;\n"
" if(!a.browser_download_url||!a.browser_download_url.startsWith('https://github.com/skiiirt1983/LyricFlash/releases/download/'))continue;\n"
" entries.push({version:r.tag_name,url:a.browser_download_url,label:(r.prerelease?'BETA':'STABLE')+' '+r.tag_name,channel:r.prerelease?'Beta':'Stable'});\n"
" }} }catch(e){errors.push('Releases: '+e.message);}\n"
" try{\n"
" const m=await get('https://skiiirt1983.github.io/LyricFlash/beta/manifest.json');\n"
" if(m.version&&m.builds?.some(b=>b.chipFamily==='ESP32-S3')){\n"
" const v=m.version;\n"
" if(!entries.some(x=>x.version===v))\n"
" entries.unshift({version:v,url:'https://skiiirt1983.github.io/LyricFlash/beta/firmware/lyricflash-ota.bin',label:'BETA '+v,channel:'Beta'});\n"
" }}catch(e){errors.push('Current Beta: '+e.message)}\n"
" const select=el('builds');select.replaceChildren(new Option(entries.length?'Choose a firmware version':'No published builds available',''));\n"
" for(let i=0;i<entries.length;i++){const b=entries[i];select.add(new Option(b.label+(i===0?'  — NEW':'')+(b.version===installed?'  — INSTALLED':''),String(i)))}\n"
" select.disabled=!entries.length;el('install').disabled=!entries.length;\n"
" el('build-info').textContent=entries.length?entries.length+' published OTA build(s) available from GitHub. Firmware installs preserve Wi-Fi.':errors.length?'Build catalog unavailable: '+errors.join('; '):'No public GitHub Releases or Beta firmware are available yet.';\n"
"}\n"
"el('builds').onchange=()=>{const b=entries[Number(el('builds').value)];el('install').disabled=!b;};\n"
"el('install').onclick=async()=>{\n"
" const b=entries[Number(el('builds').value)];if(!b)return info('Select a build first');\n"
" if(!confirm('Install '+b.version+'? Device will download it from GitHub, validate it and reboot. Wi-Fi settings will be kept.'))return;\n"
" try{el('install').disabled=true;info('Starting download on device…');\n"
" let r=await fetch('/api/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:b.url,version:b.version})});\n"
" const text=await r.text();if(!r.ok)throw Error(text);info(text);pollProgress();\n"
" }catch(e){info('Could not start firmware update: '+e.message);el('install').disabled=false}\n"
"};\n"
"async function pollProgress(){for(let i=0;i<300;i++){await new Promise(r=>setTimeout(r,1000));try{\n"
" const d=await get('/api/info');const result=d.ota_result||'unknown';\n"
" info('Status: '+result+(d.ota_total?' · '+Math.round(100*(d.ota_received||0)/d.ota_total)+'%':''));\n"
" if(result==='verified_rebooting'||result==='complete'){info('Firmware verified; device restarting…');return}\n"
" if(result.endsWith('_failed')||result==='bad_version'||result==='invalid_url'||result==='download_failed'){el('install').disabled=false;return}\n"
" }catch(e){info('Device connection interrupted. It may be restarting; reconnect to confirm version.');return}}}\n"
"el('upload').onclick=()=>{\n"
" const f=el('bin').files[0];if(!f)return el('upload-status').textContent='Select an application-only OTA image';\n"
" if(!confirm('Upload '+f.name+' as OTA firmware? Wi-Fi settings remain saved.'))return;\n"
" const button=el('upload'),xhr=new XMLHttpRequest();button.disabled=true;\n"
" xhr.open('POST','/update');xhr.timeout=180000;xhr.setRequestHeader('Content-Type','application/octet-stream');\n"
" xhr.upload.onprogress=e=>el('upload-status').textContent=e.lengthComputable?'Uploading '+Math.round(e.loaded/e.total*100)+'%':'Uploading…';\n"
" xhr.onload=()=>{button.disabled=false;el('upload-status').textContent=xhr.status>=200&&xhr.status<300?xhr.responseText:'Upload rejected: '+xhr.responseText};\n"
" xhr.onerror=()=>{button.disabled=false;el('upload-status').textContent='Connection error'};\n"
" xhr.ontimeout=()=>{button.disabled=false;el('upload-status').textContent='Upload timed out'};\n"
" xhr.send(f);\n"
"};\n"
"loadInstalled().then(loadBuilds);\n"
"</script></body></html>\n"
;
